import {test,expect} from '@playwright/test';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,existsSync,rmSync} from 'node:fs';
import {tmpdir,userInfo} from 'node:os';
import {join,resolve} from 'node:path';
import {spawn,spawnSync,type ChildProcess} from 'node:child_process';
import {createServer} from 'node:net';
import {makeSlackSource} from './slack-fixture';
let dir:string,socket:string,base:string,project:string,other:string,backend:ChildProcess,sshd:ChildProcess|undefined;
function command(program:string,args:string[]){const result=spawnSync(program,args,{encoding:'utf8',env:{...process.env,TMUX:''}});if(result.status!==0)throw Error(result.stderr);return result.stdout.trim();}
function tm(...args:string[]){return command('tmux',['-S',socket,...args]);}
async function port(){return new Promise<number>(r=>{const s=createServer();s.listen(0,'127.0.0.1',()=>{const p=(s.address() as {port:number}).port;s.close(()=>r(p));});});}
async function api(path:string,body?:unknown,method=body===undefined?'GET':'POST'){return fetch(base+'/api/v1/slack/'+path,{method,headers:body===undefined?undefined:{Origin:base,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});}
async function settings(){return(await api('settings')).json();}
async function configure(path=project,host='local'){
 const current=await settings(),hosts=await(await fetch(base+'/api/v1/hosts')).json();const machine=hosts.find((h:{id:string})=>h.id===host);const response=await api('settings',{revision:current.revision,host,connection_revision:machine.connection_revision,project:path},'PUT');expect(response.status).toBe(200);return response.json();
}
async function read(operation:string,args:Record<string,unknown>={},source?:{revision:string;connection_revision:string}){const config=source||await settings();return api('read',{revision:config.revision,connection_revision:config.connection_revision,operation,...args});}
const calls=(path=project)=>existsSync(join(path,'calls.jsonl'))?readFileSync(join(path,'calls.jsonl'),'utf8').trim().split('\n').filter(Boolean).map(line=>JSON.parse(line)):[];
function data(path=project){return JSON.parse(readFileSync(join(path,'fixture.json'),'utf8'));}
function update(patch:Record<string,unknown>,path=project){writeFileSync(join(path,'fixture.json'),JSON.stringify({...data(path),...patch}));}
test.beforeAll(async()=>{
 dir=mkdtempSync(join(tmpdir(),'cc-slack-browser-'));socket=join(dir,'tmux.sock');project=join(dir,"source ' literal");other=join(dir,'other-source');makeSlackSource(project);makeSlackSource(other,{messages:[{ts:'1700000300.000001',user:'U000001',text:'OTHER_SOURCE_ONLY'}]});
 tm('-f','/dev/null','new-session','-d','-s','terminal','-c',project,'-x','120','-y','35','/bin/sleep','86400');let remote='';
 if(existsSync('/usr/sbin/sshd')){
  command('ssh-keygen',['-q','-t','ed25519','-N','','-f',join(dir,'hostkey')]);command('ssh-keygen',['-q','-t','ed25519','-N','','-f',join(dir,'identity')]);writeFileSync(join(dir,'authorized_keys'),readFileSync(join(dir,'identity.pub')),{mode:0o600});const sshPort=await port();
  writeFileSync(join(dir,'sshd_config'),`Port ${sshPort}\nListenAddress 127.0.0.1\nHostKey ${dir}/hostkey\nAuthorizedKeysFile ${dir}/authorized_keys\nStrictModes no\nPasswordAuthentication no\nKbdInteractiveAuthentication no\nUsePAM no\nPidFile ${dir}/sshd.pid\nAllowUsers ${userInfo().username}\nLogLevel ERROR\n`);sshd=spawn('/usr/sbin/sshd',['-D','-e','-f',join(dir,'sshd_config')],{stdio:'pipe'});
  writeFileSync(join(dir,'known_hosts'),`[127.0.0.1]:${sshPort} ${readFileSync(join(dir,'hostkey.pub'),'utf8')}`);writeFileSync(join(dir,'ssh_config'),`Host slack-fixture\n HostName 127.0.0.1\n Port ${sshPort}\n User ${userInfo().username}\n IdentityFile ${dir}/identity\n IdentitiesOnly yes\n UserKnownHostsFile ${dir}/known_hosts\n`);remote=`\n[[hosts]]\nid="ssh"\nname="SSH Slack source"\nssh="slack-fixture"\nssh_config=${JSON.stringify(join(dir,'ssh_config'))}\nsocket=${JSON.stringify(socket)}\n`;
 }
 const p=await port();base=`http://127.0.0.1:${p}`;const config=join(dir,'config.toml');writeFileSync(config,`[[hosts]]\nid="local"\nname="Local Slack source"\nsocket=${JSON.stringify(socket)}\n${remote}`);
 backend=spawn(resolve(process.env.CC_BINARY||'../target/debug/command-center'),['--listen',`127.0.0.1:${p}`,'--config',config,'--web-dir',resolve(process.env.CC_WEB_DIR||'dist')],{stdio:'pipe'});await expect.poll(async()=>{try{return(await fetch(base+'/api/v1/health')).status;}catch{return 0;}}).toBe(200);
});
test.afterAll(()=>{backend?.kill('SIGTERM');sshd?.kill('SIGTERM');if(socket)spawnSync('tmux',['-S',socket,'kill-server']);if(dir)rmSync(dir,{recursive:true,force:true});});

test('read-only backend scopes credentials and cache, pages data and honors rate-limit cooldowns',async()=>{
 const config=await configure();const channels=await read('channels');expect(channels.status).toBe(200);expect(channels.headers.get('cache-control')).toContain('no-store');const page=await channels.json();expect(page.channels).toHaveLength(2);expect(page.next_cursor).toBe('more');
 const before=calls().length;expect((await read('channels')).status).toBe(200);expect(calls().length).toBe(before);
 const history=await read('history',{channel:'C000001'});const raw=await history.text();expect(raw).not.toContain('FAKE_AUTH_SECRET');expect(raw).not.toContain('FAKE_COOKIE_SECRET');expect(raw).not.toContain('url_private');expect(JSON.parse(raw).messages[0].author).toBe('alice');
 expect((await read('history',{channel:'C000001',cursor:'older'})).status).toBe(200);expect((await read('thread',{channel:'C000001',ts:'1700000000.000001'})).status).toBe(200);expect((await read('search',{query:'in:engineering'})).status).toBe(200);
 const count=calls().length;expect((await read('chat.postMessage')).status).toBe(400);expect((await read('history',{channel:'../../etc/passwd'})).status).toBe(400);expect(calls().length).toBe(count);expect((await read('channels',{}, {...config,connection_revision:'stale'})).status).toBe(409);
 update({rate:true});expect((await read('history',{channel:'C000001',refresh:true})).status).toBe(429);const limited=calls().length;expect((await read('history',{channel:'C000001',refresh:true})).status).toBe(429);expect(calls().length).toBe(limited);update({rate:false});
});

test('Slack source can read over SSH without copying credentials or accepting stale integration settings',async()=>{
 test.skip(!sshd,'OpenSSH server unavailable');const config=await configure(project,'ssh');const response=await read('history',{channel:'C000001'});expect(response.status,await response.clone().text()).toBe(200);expect((await response.json()).messages).toHaveLength(2);
 const next=await configure(other,'ssh');expect((await read('history',{channel:'C000001'},config)).status).toBe(409);const fresh=await read('history',{channel:'C000001'},next);expect(await fresh.text()).toContain('OTHER_SOURCE_ONLY');
});

test('channels, history, threads and search render safely while terminal selection and processes survive',async({page})=>{
 await configure();await page.goto(base);await expect(page.locator('#connection')).toHaveText('Attached');const pids=tm('list-panes','-a','-F','#{pane_pid}');
 await page.locator('#show-slack').click();await expect(page.getByRole('button',{name:'# engineering',exact:true})).toBeVisible();await page.getByRole('button',{name:'# engineering',exact:true}).click();const history=page.getByLabel('Slack message history',{exact:true});await expect(history).toContainText('Latest update with code and @bob');const original=data();update({messages:[...original.messages,{ts:'1700000400.000001',user:'U000001',text:'New subscribed channel message'}]});await page.getByRole('button',{name:'Refresh messages',exact:true}).click();await expect(history).toContainText('New subscribed channel message');update({messages:original.messages});expect(await history.locator('img,script,a[href^="javascript:"]').count()).toBe(0);
 await expect(page.locator('#terminal-pane')).toBeHidden();await page.getByRole('button',{name:'Older messages',exact:true}).click();await expect(history).toContainText('An older message');
 await page.getByRole('button',{name:'2 replies',exact:true}).click();await expect(page.getByLabel('Slack thread replies',{exact:true})).toContainText('First reply');await page.getByRole('button',{name:'More replies',exact:true}).click();await expect(page.getByLabel('Slack thread replies',{exact:true})).toContainText('Second reply');await page.screenshot({path:'../test-results/slack-desktop.png'});await page.getByRole('button',{name:'Close thread',exact:true}).click();
 await page.getByRole('searchbox',{name:'Search Slack',exact:true}).fill('in:product roadmap');await page.getByRole('button',{name:'Search',exact:true}).click();await expect(history).toContainText('Search result text');await expect(page.getByRole('button',{name:'# product',exact:true})).toBeVisible();
 expect(tm('list-panes','-a','-F','#{pane_pid}')).toBe(pids);await page.locator('#show-terminal').click();await expect(page.locator('#connection')).toHaveText('Attached');
});

test('phone Slack navigation never attaches a terminal or changes a desktop viewer size',async({page,browser})=>{
 await configure();await page.goto(base);await expect(page.locator('#connection')).toHaveText('Attached');const before=tm('display-message','-p','-t','terminal','#{window_width}x#{window_height}/#{pane_pid}');
 const phone=await browser.newPage({viewport:{width:393,height:852},isMobile:true,hasTouch:true});let sockets=0;phone.on('websocket',ws=>{if(ws.url().includes('/terminal?'))sockets++;});await phone.goto(base);await phone.locator('#toggle-files').click();await expect(phone.locator('#files-pane')).toBeVisible();await phone.locator('#show-slack').click();await phone.getByRole('button',{name:'# engineering',exact:true}).click();await expect(phone.getByLabel('Slack message history',{exact:true})).toContainText('Latest');await phone.getByRole('button',{name:'2 replies',exact:true}).click();await expect(phone.getByLabel('Slack thread replies',{exact:true})).toContainText('First reply');await phone.screenshot({path:'../test-results/slack-phone.png'});
 expect(await phone.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect(sockets).toBe(0);expect(tm('display-message','-p','-t','terminal','#{window_width}x#{window_height}/#{pane_pid}')).toBe(before);await phone.getByRole('button',{name:'Close thread',exact:true}).click();await phone.getByRole('button',{name:'Channels',exact:true}).click();await expect(phone.getByRole('navigation',{name:'Slack channels',exact:true})).toBeVisible();await phone.close();
});

test('changing the source during a slow read discards the old result and settings never store secrets',async()=>{
 const config=await configure();update({delay:true});if(existsSync(join(project,'started')))rmSync(join(project,'started'));const pending=read('history',{channel:'C000001',refresh:true},config);await expect.poll(()=>existsSync(join(project,'started'))).toBe(true);await configure(other);const response=await pending;expect(response.status).toBe(409);expect(await response.text()).not.toContain('Latest');update({delay:false});
 const metadata=readFileSync(join(dir,'config.slack.json'),'utf8');expect(metadata).not.toContain('FAKE_AUTH_SECRET');expect(metadata).not.toContain('FAKE_COOKIE_SECRET');expect(JSON.parse(metadata).source.project).toBe(other);
});

