async function localState(action='get',args:Record<string,unknown>={},source?:{revision:string;connection_revision:string}){const s=source||await settings();return api('state',{revision:s.revision,connection_revision:s.connection_revision,action,...args});}
test('CC unread metadata is monotonic, shared across clients, scoped and durable without message text',async()=>{
 const s=await configure();update({enterprise:true,latest:{C000001:'1700000100.000002'}});await read('channels');let state=await(await localState()).json();expect(state.channels.C000001.read).toBe('1700000100.000002');
 update({latest:{C000001:'1700000500.000001'}});await read('channels',{refresh:true});state=await(await localState()).json();expect(state.channels.C000001.latest).toBe('1700000500.000001');expect(state.channels.C000001.read).toBe('1700000100.000002');
 expect((await localState('read',{channel:'C000001',ts:'9999999999.000001'})).status).toBe(409);expect((await localState('pin',{channel:'C000001',pinned:true})).status).toBe(200);
 await localState('read',{channel:'C000001',ts:'1700000500.000001'});await localState('read',{channel:'C000001',ts:'1700000100.000002'});expect((await(await localState()).json()).channels.C000001.read).toBe('1700000500.000001');
 const persisted=readFileSync(join(dir,'config.slack.state.json'),'utf8');expect(persisted).not.toContain('Latest update');expect(persisted).not.toContain('FAKE_AUTH_SECRET');expect(JSON.parse(persisted).channels.C000001.pinned).toBe(true);
 await configure(other);expect((await localState('pin',{channel:'C000001',pinned:false},s)).status).toBe(409);expect((await(await localState()).json()).channels).toEqual({});update({enterprise:false});
});
