async function sendFixture(text:string,extra:Record<string,unknown>={},source?:{revision:string;connection_revision:string}){const s=source||await settings();return api('send',{revision:s.revision,connection_revision:s.connection_revision,id:crypto.randomUUID(),channel:'C000001',text,...extra});}
const posts=()=>calls().filter(c=>c.endpoint==='chat.postMessage');
test('explicit sends are deduplicated, target native thread roots, and persist only metadata',async()=>{
 const s=await configure();update({allow_write:true});const id=crypto.randomUUID(),before=posts().length;const response=await sendFixture('Fixture send',{id,thread_ts:'1700000000.000001'},s);expect(response.status,await response.clone().text()).toBe(200);expect((await response.json()).status).toBe('sent');expect(posts().length).toBe(before+1);expect(posts().at(-1).payload.thread_ts).toBe('1700000000.000001');
 expect((await(await sendFixture('Fixture send',{id,thread_ts:'1700000000.000001'},s)).json()).status).toBe('sent');expect(posts().length).toBe(before+1);expect((await sendFixture('Changed text',{id},s)).status).toBe(409);expect((await sendFixture('Fixture',{connection_revision:'stale'},s)).status).toBe(409);
 const raw=readFileSync(join(dir,'config.slack.sends.json'),'utf8');expect(raw).not.toContain('Fixture send');expect(raw).not.toContain('FAKE_AUTH_SECRET');expect(posts().at(-1).payload.reply_broadcast).toBe(false);expect(posts().at(-1).payload.unfurl_links).toBe(false);expect(calls().some(c=>c.endpoint==='conversations.join')).toBe(false);
});
test('uncertain delivery is retained across replay and safe failures preserve the draft',async()=>{
 await configure();update({post_uncertain:true,allow_write:true});const id=crypto.randomUUID(),count=posts().length;expect((await(await sendFixture('Uncertain fixture',{id})).json()).status).toBe('uncertain');expect((await(await sendFixture('Uncertain fixture',{id})).json()).status).toBe('uncertain');expect(posts().length).toBe(count+1);const s=await settings();const status=await api('send/status',{revision:s.revision,connection_revision:s.connection_revision,id});expect((await status.json()).status).toBe('uncertain');
 update({post_uncertain:false,allow_write:false});const denied=await sendFixture('Permission fixture');expect((await denied.json()).status).toBe('failed');expect(posts().length).toBe(count+1);update({allow_write:true,post_error:'not_in_channel'});expect((await(await sendFixture('Rejected fixture')).json()).status).toBe('failed');update({post_error:null});
});
