async function gesturePhone(browser:import('@playwright/test').Browser){
 await configure();update({allow_write:false,gesture_threads:true,thread_error:null,thread_delay:false,messages:Array.from({length:16},(_,i)=>({ts:`1700000${String(200+i)}.000001`,user:'U000001',text:`Gesture message ${i} ${'Readable conversation text. '.repeat(12)}${i===1?' <https://example.test/|Fixture link> `fixture_code`':''}`,reply_count:i===0?2:0,...(i===2?{thread_ts:threadRoot}:{})}))});const phone=await browser.newPage({viewport:{width:393,height:852},isMobile:true,hasTouch:true});await phone.goto(base);await phone.locator('#show-slack').click();await phone.getByRole('button',{name:'# engineering',exact:true}).click();await expect(phone.getByLabel('Slack message history',{exact:true})).toContainText('Gesture message');return phone;
}
async function touchHold(page:import('@playwright/test').Page,locator:import('@playwright/test').Locator,move=false){await locator.scrollIntoViewIfNeeded();const box=await locator.boundingBox();const cdp=await page.context().newCDPSession(page);const x=box!.x+8,y=box!.y+14;await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y}]});if(move)await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x,y:y-45}]});await page.waitForTimeout(650);await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await cdp.detach();}
test('compact messages open threads by double-tap, hold and keyboard without repeated visual buttons',async({browser})=>{
 const phone=await gesturePhone(browser);const requests:Array<{channel:string;ts:string}>=[];phone.on('request',r=>{if(r.url().endsWith('/api/v1/slack/read')&&r.method()==='POST'){const body=r.postDataJSON();if(body.operation==='thread')requests.push(body);}});const history=phone.getByLabel('Slack message history',{exact:true});const plain=history.locator('article[data-ts="1700000201.000001"]');await plain.scrollIntoViewIfNeeded();expect(await plain.locator('.slack-open-thread').evaluate(n=>n.getBoundingClientRect().height)).toBeLessThanOrEqual(1);await expect(history.getByRole('button',{name:'2 replies',exact:true})).toBeVisible();let box=await plain.locator('.slack-message-text').boundingBox();await phone.touchscreen.tap(box!.x+8,box!.y+14);await phone.touchscreen.tap(box!.x+8,box!.y+14);await expect(phone.getByLabel('Slack thread replies',{exact:true})).toContainText('Gesture thread root');expect(requests).toHaveLength(1);expect(requests[0].ts).toBe('1700000201.000001');await phone.getByRole('button',{name:'Close thread',exact:true}).click();
 await phone.evaluate(()=>getSelection()?.removeAllRanges());await touchHold(phone,history.locator('article[data-ts="1700000202.000001"] .slack-message-text'));await expect(phone.getByLabel('Slack thread replies',{exact:true})).toContainText('Gesture thread root');expect(requests).toHaveLength(2);expect(requests[1].ts).toBe(threadRoot);await phone.getByRole('button',{name:'Close thread',exact:true}).click();await plain.focus();await plain.press('Enter');await expect(phone.getByLabel('Slack thread replies',{exact:true})).toContainText('Gesture thread root');expect(requests).toHaveLength(3);await phone.getByRole('button',{name:'Close thread',exact:true}).click();await phone.screenshot({path:'../test-results/slack-message-gestures-phone.png'});await phone.close();
});
test('scrolling, links, code and an existing selection do not trigger compact thread gestures',async({browser})=>{
 const phone=await gesturePhone(browser);let requests=0;phone.on('request',r=>{if(r.url().endsWith('/api/v1/slack/read')&&r.method()==='POST'&&r.postDataJSON().operation==='thread')requests++;});const history=phone.getByLabel('Slack message history',{exact:true}),body=history.locator('article[data-ts="1700000201.000001"] .slack-message-text');await touchHold(phone,body,true);expect(requests).toBe(0);await expect(phone.getByRole('button',{name:'Close thread',exact:true})).toBeHidden();await body.scrollIntoViewIfNeeded();const dragBox=await body.boundingBox();await phone.mouse.move(dragBox!.x+8,dragBox!.y+14);await phone.mouse.down();await phone.mouse.move(1,1);await phone.mouse.up();await phone.waitForTimeout(650);expect(requests).toBe(0);const link=history.getByRole('link',{name:'Fixture link',exact:true});await link.evaluate(n=>n.addEventListener('click',e=>e.preventDefault()));await link.dblclick();await history.locator('code').dblclick();expect(requests).toBe(0);
 await body.scrollIntoViewIfNeeded();await body.evaluate(n=>{const range=document.createRange();range.selectNodeContents(n);getSelection()?.removeAllRanges();getSelection()?.addRange(range);});await touchHold(phone,body);expect(requests).toBe(0);await phone.evaluate(()=>getSelection()?.removeAllRanges());await phone.close();
});
test('desktop double-click keeps native text selection and explicit thread buttons',async({page})=>{
 await configure();await page.goto(base);await page.locator('#show-slack').click();await page.getByRole('button',{name:'# engineering',exact:true}).click();const history=page.getByLabel('Slack message history',{exact:true});await expect(history.locator('article')).not.toHaveCount(0);await history.locator('.slack-message-text').first().dblclick();expect(await page.evaluate(()=>getSelection()?.toString().length||0)).toBeGreaterThan(0);await expect(page.getByRole('button',{name:'Close thread',exact:true})).toBeHidden();await expect(history.getByRole('button',{name:'Open thread',exact:true}).first()).toBeVisible();
});
